const routes = $input.all()[0].json.routes;

// Sort routes by duration_in_traffic if available, else duration
const bestRoute = routes.sort((a, b) => {
 const timeA = a.legs[0].duration_in_traffic ? a.legs[0].duration_in_traffic.value : a.legs[0].duration.value;
 const timeB = b.legs[0].duration_in_traffic ? b.legs[0].duration_in_traffic.value : b.legs[0].duration.value;
 return timeA - timeB;
})[0];

const durationTraffic = bestRoute.legs[0].duration_in_traffic ? bestRoute.legs[0].duration_in_traffic.text : bestRoute.legs[0].duration.text;
const durationNormal = bestRoute.legs[0].duration.text;

return [{
  json: {
    summary: bestRoute.summary,
    duration_traffic: durationTraffic,
    distance: bestRoute.legs[0].distance.text,
    message: `🚗 *Commute Update*\n\nRoute: ${bestRoute.summary}\nDistance: ${bestRoute.legs[0].distance.text}\nTraffic Time: *${durationTraffic}*\n(Normal: ${durationNormal})`
  }
}];
